def generate(seed):
    r = random.Random(seed)
    for _ in range(600):
        W = r.randint(9, 16)
        base = [r.choice("##oo...") for _ in range(W)]
        if sum(ch != "." for ch in base) < 4:
            continue
        rows = [base]; n = 0
        for _ in range(r.randint(3, 6)):
            prev = rows[-1]
            A = []; B = []
            for j in range(W):
                k = sum(prev[x] != "." for x in (j - 1, j, j + 1) if 0 <= x < W)
                if k == 2 and prev[j] != "#":
                    A.append(j)
                elif k == 1 and prev[j] != "o":
                    B.append(j)
            if not A and not B:
                break
            r.shuffle(A); r.shuffle(B)
            nxt = ["."] * W
            for j in A[:r.choice([len(A), len(A), r.randint(0, len(A))])]:
                nxt[j] = "#"
            for j in B[:r.randint(0, len(B))]:
                nxt[j] = "o"
            if all(ch == "." for ch in nxt):
                break
            n += nxt.count("#")
            rows.append(nxt)
        if 3 <= n <= 26:
            return "".join(base) + "|" + str(n)
    return "#o..#.#o.|3"

