def solve(clue):
    """Raise a picture on the given ground row holding exactly n stones above the ground.

    Every row above is determined by the row directly below it: a stone may stand where
    exactly two of the three cells below are occupied AND the cell directly below is not
    itself a stone; wood where exactly one is occupied AND the cell directly below is not
    itself wood (nothing rests on its own kind).  So we walk upward, spending the stone
    quota and scattering wood for scaffolding and camouflage; randomised by the clue.
    """
    f, ns = clue.split("|")
    n = int(ns); W = len(f)
    r = random.Random(clue)

    def opts(prev):
        A = []; B = []
        for j in range(W):
            k = sum(prev[x] != "." for x in (j - 1, j, j + 1) if 0 <= x < W)
            if k == 2 and prev[j] != "#":
                A.append(j)
            elif k == 1 and prev[j] != "o":
                B.append(j)
        return A, B

    for _ in range(400):
        rows = [list(f)]
        rem = n
        for _ in range(9):
            if rem == 0:
                break
            A, B = opts(rows[-1])
            if not A and not B:
                break
            r.shuffle(A); r.shuffle(B)
            nxt = ["."] * W
            take = min(len(A), rem)
            if take and r.random() < .3:
                take = r.randint(1, take)
            for j in A[:take]:
                nxt[j] = "#"
            rem -= take
            if B and (not take or r.random() < .7):
                for j in B[:r.randint(1, len(B))]:
                    nxt[j] = "o"
            if all(ch == "." for ch in nxt):
                break
            rows.append(nxt)
        if rem:
            continue
        for _ in range(r.randint(0, 2)):          # wood-only attic: never changes the count
            B = opts(rows[-1])[1]
            if not B:
                break
            r.shuffle(B)
            nxt = ["."] * W
            for j in B[:r.randint(1, len(B))]:
                nxt[j] = "o"
            rows.append(nxt)
        return "\n".join("".join(x) for x in rows[::-1])
    return ""

